WITH base AS (SELECT id, device_code, reading_ts, temp_c, humidity, pressure, status_bits, firmware, pressure * status_bits pressure_times_status_bits FROM device_readings WHERE temp_c >= 35), metrics AS (SELECT id, humidity, firmware, AVG(pressure) OVER (PARTITION BY device_code ORDER BY pressure_times_status_bits, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) pressure_avg_2, NTILE(4) OVER (PARTITION BY device_code ORDER BY status_bits, id) status_bits_bucket, PERCENT_RANK() OVER (PARTITION BY device_code ORDER BY pressure_times_status_bits) pressure_times_status_bits_percent_rank FROM base), valid AS (SELECT id, humidity, firmware, pressure_avg_2, pressure_times_status_bits_percent_rank, ROUND(humidity, 2) humidity_rounded FROM metrics WHERE status_bits_bucket <= 4), with_windows AS (SELECT *, LEAD(pressure_avg_2) OVER w_part next_pressure_avg_2, LAG(humidity) OVER w_part prev_humidity, LEAD(humidity) OVER w_part next_humidity, ROW_NUMBER() OVER w_part seq_no FROM valid WHERE pressure_times_status_bits_percent_rank >= 0.68 WINDOW w_part AS (ORDER BY pressure_avg_2, id)), summary AS (SELECT CASE WHEN pressure_avg_2 >= 1026 THEN 'HIGH' ELSE 'LOW' END AS pressure_avg_2_tier, seq_no, CASE WHEN prev_humidity >= 65 THEN 'PREMIUM' ELSE 'STANDARD' END AS prev_humidity_tier, PERCENTILE_APPROX(next_humidity, 0.5) AS next_humidity_p50, COUNT(DISTINCT id) AS distinct_ids, COUNT(DISTINCT id) AS distinct_ids_2, PERCENTILE_APPROX(humidity_rounded, 0.9) AS humidity_rounded_p90, AVG(next_pressure_avg_2) AS avg_next_pressure_avg_2, COUNT(*) AS event_count FROM with_windows GROUP BY CASE WHEN pressure_avg_2 >= 1026 THEN 'HIGH' ELSE 'LOW' END, seq_no, CASE WHEN prev_humidity >= 65 THEN 'PREMIUM' ELSE 'STANDARD' END HAVING COUNT(DISTINCT id) > 1) SELECT pressure_avg_2_tier, seq_no, prev_humidity_tier, distinct_ids, distinct_ids_2, humidity_rounded_p90, avg_next_pressure_avg_2 FROM summary ORDER BY distinct_ids NULLS FIRST, humidity_rounded_p90
